export const GetServiceAndComponentAllData = async (Props?: any | null, filter?: any | null) => {
    if (!Props?.siteUrl) {
        return processGetServiceAndComponentAllDataCore(Props, filter);
    }
    const csfFilter = filter || DEFAULT_CSF_FILTER;
    // Include projectSelection in the key — picker vs portfolio paths differ.
    // "csf-pxc-processed" also busts older CSF-only caches that had empty ProjectData.
    // Deliberately NOT including csfFilter in the key: fetchMasterListCSFRaw ignores its
    // filter argument (always reads the full per-type dump), so every caller's result is
    // identical regardless of the filter string passed in. Keying by it used to fragment
    // this cache into one entry per portfolio item (each paying the full processing cost),
    // which is why Team Portfolio -> Portfolio Profile was slow while Project Overview ->
    // PXC Profile (whose GetPXCData cache key has no such per-item filter) was instant.
    const cacheKey = `${masterListSiteKey(Props.siteUrl)}::csf-pxc-processed::ps=${Props?.projectSelection === true ? "1" : "0"}`;
    const cached = masterListProcessedCache.get(cacheKey);
    if (cached && masterListFresh(cached.loadedAt)) {
        return cloneMasterList(cached.data);
    }
    let pending = masterListProcessedInFlight.get(cacheKey);
    if (!pending) {
        pending = processGetServiceAndComponentAllDataCore(Props, filter).then((data) => {
            if (data) {
                masterListProcessedCache.set(cacheKey, { data, loadedAt: Date.now() });
            }
            return data;
        }).finally(() => {
            masterListProcessedInFlight.delete(cacheKey);
        });
        masterListProcessedInFlight.set(cacheKey, pending);
    }
    return pending.then((data) => cloneMasterList(data));
};

