  '/task-profile': 'Task Profile',
  '/pxc-profile': 'PXC Profile',
  '/omt': 'OMT'
};

const KNOWN_ROUTES = Object.keys(ROUTE_LABELS);

const LIST_ROUTES = ['/team-portfolio', '/project-overview', '/create-task', '/omt'];

/** Query keys that must be plain ids (digits). Corrupted values look like
 *  `12920/pxc-profile?ProjectId=12920` when a hash route was glued into search. */
const NUMERIC_ID_KEYS = ['ProjectId', 'taskId', 'TaskId', 'ComponentID', 'ComponentId'];

/** Profile-only keys that must not linger on list tools (team-portfolio, etc.). */
const PROFILE_ONLY_KEYS = ['ProjectId', 'taskId', 'TaskId', 'Site', 'SelectedView'];

/** These parameters intentionally contain paths/query strings. Sanitizing them
 * like ids or filters turns `https://...` into `https:` and breaks Create Task. */
const URL_VALUE_KEYS = ['Siteurl', 'SiteUrl', 'TaskUrl', 'siteAbsoluteUrl'];

export function getRouteLabel(route: string): string {
  return ROUTE_LABELS[route] || route;
}

/** Static through Task-Management.aspx. Only query ids (ProjectId / taskId / Site) are dynamic. */
export const TASK_MANAGEMENT_PAGE_URL =
  'https://hhhhteams.sharepoint.com/sites/HHHH/SP/SitePages/Task-Management.aspx';

/** Path only — strip accidental `?query` from route strings. */
function normalizeRoute(route: string): string {
  const withSlash = route.startsWith('/') ? route : `/${route}`;
  const pathOnly = withSlash.split('?')[0] || '/team-portfolio';
  return pathOnly.startsWith('/') ? pathOnly : `/${pathOnly}`;
}

function isListRoute(route: string): boolean {
  const normalized = normalizeRoute(route);
  return LIST_ROUTES.indexOf(normalized) !== -1;
}

/** Pull a leading integer id out of a polluted value (route/query glued on). */
function sanitizeNumericId(value: string): string {
  const match = String(value).match(/^\d+/);
  return match ? match[0] : '';
}

