import * as React from 'react';
import { useHistory } from 'react-router-dom';
import { mapHrefToSpa, navigateSpa } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/spaNavigation';

/**
 * Safety net: intercept leftover SitePages / #/ profile links that were not
 * converted to NavLink components. Skips anchors marked data-spa-link.
 */
export default function SpaNavigationInterceptor(): null {
  const history = useHistory();

  React.useEffect(() => {
    const onClick = (event: MouseEvent): void => {
      if (event.defaultPrevented) {
        return;
      }
      const target = event.target as HTMLElement | null;
      if (!target || !target.closest) {
        return;
      }
      const anchor = target.closest('a') as HTMLAnchorElement | null;
      if (!anchor) {
        return;
      }
      if (anchor.getAttribute('data-spa-link') === 'true') {
        return;
      }
      // Classic SharePoint pages (e.g. "Old …" links) or new tab links — let the browser handle them.
      const targetAttr = anchor.getAttribute('target');
      if (
        anchor.getAttribute('data-spa-external') === 'true' ||
        anchor.getAttribute('data-interception') === 'off' ||
        targetAttr === '_blank' ||
        targetAttr === 'blank'
      ) {
        return;
      }

      const href = anchor.getAttribute('href') || '';
      const mapped = mapHrefToSpa(href);
      if (!mapped) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      navigateSpa(history, mapped.route, mapped.params);
    };

    const originalOpen = window.open.bind(window);
    (window as any).__hhhhNativeWindowOpen = originalOpen;
    window.open = ((url?: string | URL, target?: string, features?: string) => {
      if (target === '_blank' || target === 'blank') {
        return originalOpen(url as any, target, features);
      }
      const href = url != null ? String(url) : '';
      const mapped = mapHrefToSpa(href);
      if (mapped) {
        navigateSpa(history, mapped.route, mapped.params);
        return null;
      }
      return originalOpen(url as any, target, features);
    }) as typeof window.open;

    document.addEventListener('click', onClick, true);
    return () => {
      document.removeEventListener('click', onClick, true);
      window.open = originalOpen;
      delete (window as any).__hhhhNativeWindowOpen;
    };
  }, [history]);

  return null;
}

