export function mapHrefToSpa(
  href: string | null | undefined
): { route: string; params: ISpaParams } | null {
  if (!href || href === '#' || href.toLowerCase().indexOf('javascript:') === 0) {
    return null;
  }
  if (/Task-Profile-Old\.aspx/i.test(href)) {
    return null;
  }

