  // Missed the app's own canonical link shape — Task-Management.aspx?taskId=794&Site=EPS#/task-profile —
  // where the hash is preceded by the query string, not a "/". That silently broke every
  // real task/project row link: mapHrefToSpa returned null, the interceptor did nothing, and the
  // click fell through with no visible effect (no SPA route change, no full navigation either,
  // since the anchor's own default was already suppressed elsewhere in the row).
  if (href.indexOf('#/') !== -1) {
    try {
      const hashPart = href.indexOf('#') >= 0 ? href.substring(href.indexOf('#') + 1) : href;
      const pathOnly = hashPart.split('?')[0] || '';
      const route = pathOnly.startsWith('/') ? pathOnly : `/${pathOnly}`;
      if (KNOWN_ROUTES.indexOf(route) === -1) {
        return null;
      }
      const params: ISpaParams = {};
      const beforeHash = href.split('#')[0];
      const searchIndex = beforeHash.indexOf('?');
      if (searchIndex >= 0) {
        new URLSearchParams(beforeHash.substring(searchIndex + 1)).forEach((v, k) => {
          params[k] = v;
        });
      }
      const hashQuery = hashPart.indexOf('?') >= 0 ? hashPart.substring(hashPart.indexOf('?') + 1) : '';
      if (hashQuery) {
        new URLSearchParams(hashQuery).forEach((v, k) => {
          if (params[k] === undefined) {
